const items = $input.all();
const output = [];

const TIME_ZONE = 'Asia/Seoul';

// 한국 기준 오늘 YYYY-MM-DD
function getKSTDateString(dateValue = new Date()) {
  const date = new Date(dateValue);

  if (Number.isNaN(date.getTime())) {
    return null;
  }

  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone: TIME_ZONE,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  }).formatToParts(date);

  const get = (type) =>
    parts.find(p => p.type === type)?.value;

  return `${get('year')}-${get('month')}-${get('day')}`;
}

// YYYY-MM-DD에서 N일 더하기
function addDays(dateString, days) {
  const date = new Date(`${dateString}T00:00:00Z`);
  date.setUTCDate(date.getUTCDate() + days);
  return date.toISOString().slice(0, 10);
}

const today = getKSTDateString();

for (const item of items) {
  const {
    document_id,
    store_id,
    promotion_name,
    promotion_start_date,
    promotion_end_date,

    customer_id,
    customer_name,

    privacy_consent,
    marketing_consent,
    recontact_consent,

    schedule_type,
  } = item.json;

  if (!promotion_start_date || !promotion_end_date) {
    throw new Error(
      `프로모션 시작일 또는 종료일이 없습니다. document_id=${document_id}`
    );
  }

  // 종료일 2일 전
  const endReminderDate = addDays(
    promotion_end_date,
    -2
  );

  // -----------------------------------
  // 1. 프로모션 시작일 문자
  // 시작일이 아직 지나지 않은 경우만 생성
  // -----------------------------------
  if (promotion_start_date >= today) {
    output.push({
      json: {
        document_id,
        store_id,

        customer_id,
        customer_name,

        schedule_type,

        privacy_consent,
        marketing_consent,
        recontact_consent,

        promotion_name,
        promotion_start_date,
        promotion_end_date,

        reference_date: promotion_start_date,

        schedule_subtype: 'promotion_start',

        scheduled_contact_date: promotion_start_date,

        contact_reason: '프로모션 시작 안내',
      }
    });
  }

  // -----------------------------------
  // 2. 프로모션 종료 2일 전 문자
  // 발송 예정일이 아직 지나지 않은 경우만 생성
  // -----------------------------------
  if (endReminderDate >= today) {
    output.push({
      json: {
        document_id,
        store_id,

        customer_id,
        customer_name,

        schedule_type,

        privacy_consent,
        marketing_consent,
        recontact_consent,

        promotion_name,
        promotion_start_date,
        promotion_end_date,

        reference_date: promotion_end_date,

        schedule_subtype: 'promotion_end_2d_before',

        scheduled_contact_date: endReminderDate,

        contact_reason: '프로모션 종료 2일 전 안내',
      }
    });
  }
}

return output;

const items = $input.all();

const groups = {};

for (const item of items) {
  const data = item.json;

  const key = [
    data.document_id,
    data.schedule_subtype
  ].join('|');

  if (!groups[key]) {
    groups[key] = {
      document_id: data.document_id,
      store_id: data.store_id,
      promotion_name: data.promotion_name,

      schedule_type: data.schedule_type,
      schedule_subtype: data.schedule_subtype,

      reference_date: data.reference_date,
      scheduled_contact_at: data.scheduled_contact_at,
      contact_reason: data.contact_reason,

      target_customer_count: 0,

      customer_names: [],
      customer_ids: [],
      schedule_ids: [],

      // 기존 Calendar 이벤트가 있으면 여기에 보관
      calendar_event_id: null
    };
  }

  groups[key].target_customer_count += 1;

  groups[key].customer_names.push(data.customer_name);
  groups[key].customer_ids.push(data.customer_id);
  groups[key].schedule_ids.push(data.schedule_id);

  // 같은 그룹 중 하나라도 기존 Calendar ID가 있으면 사용
  if (
    !groups[key].calendar_event_id &&
    data.calendar_event_id
  ) {
    groups[key].calendar_event_id =
      data.calendar_event_id;
  }
}

return Object.values(groups).map(group => {

  const MAX_VISIBLE_CUSTOMERS = 5;

  const visibleNames =
    group.customer_names.slice(0, MAX_VISIBLE_CUSTOMERS);

  let customerDisplay =
    visibleNames
      .map(name => `- ${name}`)
      .join('\n');

  const remaining =
    group.target_customer_count - visibleNames.length;

  if (remaining > 0) {
    customerDisplay += `\n외 ${remaining}명`;
  }

  return {
    json: {
      ...group,
      customer_display: customerDisplay
    }
  };
});
